# T-11 prompts. Run: python3 prompts_t11.py -> reqs_t11.json (in cwd)
import json
S="HD-2D pixel art, Octopath Traveler style, crisp pixel sprites, painterly diorama background, tilt-shift miniature depth, dramatic warm ember light against cold dusk, volumetric fog, high fantasy, no text, no watermark, no UI"
MAG="The entire background is a perfectly flat, uniform pure magenta #FF00FF color with no gradient, no shadow, no texture."
BIBLE="c05564d4-14be-4f28-b5a3-8cba21e153b4"; HERO="b38cc065-5b75-4ad2-8532-ec4bb89ce6e3"; PORT="42d2780e-2eb9-45f7-af15-09a8e450caec"
REF2="First reference image: art style only, do not copy its composition. Second reference image: copy its layout, framing and character rendering only."
RELICS=["a burning branding iron","a heavy brass-clasped warden's cloak, folded","a small glass vial of glowing phoenix ash with a red feather","a tiny brass bellows charm on a cord","a brass-rimmed seer's monocle lens with a glint","a dark iron executioner's coin stamped with an axe","a golden sunsteel whetstone, glowing edge","a bundle of kindling sticks tied with twine","three sharp iron arrowheads fanned out","a smoky ashen hourglass with grey sand","a small iron pan of glowing banked coals","a coiled crimson silk ribbon","a small leather prayer book with a brass flame clasp","a fat gilded coin purse with gold coins","a small lit candle stub on a brass holder","a brass tinderbox with flint and a spark"]
grid=" ".join(f"{i+1}. {d}." for i,d in enumerate(RELICS))
P={
 "relics":("gpt_image_2_6","1:1",[BIBLE],f"{S}. Use the reference image only for art style and warm brass/ember palette, do not copy its scene. A 4x4 grid sheet of 16 pixel-art item icons for a fantasy RPG inventory, each icon a single centered object in its own equal cell, chunky readable silhouette, thick dark outline, warm brass and ember palette, consistent top-left lighting, all at a similar size with generous empty space around each, no frames, no grid lines, no labels. Row-major order (left to right, top to bottom): {grid} {MAG}"),
 "mira_sprite":("nano_banana_pro","1:1",[BIBLE,HERO],f"{S}. {REF2} Single character sprite, full body, side view facing RIGHT, idle stance, same pixel-art scale and rendering as the hero sprites: Mira, a kind white-haired old woman wagon driver, long white hair in a loose bun, a green knitted shawl over a simple brown dress, leaning on a gnarled wooden walking staff, a small warm ember glint in her eyes. Centered with generous empty space around her. No ground, no shadows, no wagon, no other characters. {MAG}"),
 "mira_portraits":("nano_banana_pro","16:9",[BIBLE,PORT],f"{S}. {REF2} Two chest-up character portraits side by side, each filling one half of the frame, 3/4 view, painterly HD-2D character art, dark warm vignette background lit by ember light, a thin dark gap between the halves, same framing and head size as the reference portraits. Left half: Mira, a kind weathered old woman with white hair in a loose bun, wrinkled gentle face, a green knitted shawl over a brown dress, a warm ember-orange glint in her eyes. Right half: the same woman as a young girl of about ten, same facial features, the same white hair, faintly glowing ember-orange eyes, wearing the same green shawl, solemn and wondering expression."),
 "cg_twist":("nano_banana_pro","16:9",[BIBLE,HERO],f"{S}. First reference image: art style only, do not copy its composition. Second reference image: the four heroes' designs only. Story CG at night in the frozen Frostspire Pass, blue-white snow, aurora overhead: an old white-haired woman in a green shawl stands in the snow, her silhouette dissolving upward into glowing ember light and sparks; beside her a small lantern on a wooden wagon holds a young living flame whose tendrils reach toward her. Four heroes look on in awe from the side: an armored knight with a kite shield, a green-hooded ranger with a longbow, a crimson-robed priest with a brass censer, a nimble duelist in a tan cloak with two short blades. Emotional, cinematic, cold blue night against warm ember glow."),
 "cg_epilogue":("nano_banana_pro","16:9",[BIBLE],f"{S}. Use the reference image only for art style, do not copy its composition. Story CG epilogue: the giant golden brazier atop the central gate of the ruined golden city of Solenne blazing back to life with a towering warm flame, golden light flooding across the ruined domes, towers and streets and pushing back grey ash, dawn breaking on the horizon in pink and gold. Small in the foreground on a road, a tiny caravan with a wooden lantern-wagon and a few small figures looking up. Triumphant, hopeful, warm."),
 "map":("nano_banana_pro","16:9",[BIBLE],f"Painted fantasy world map on aged parchment paper, hand-painted watercolor and ink style with a subtle HD-2D painterly feel, top-down illustrated map, no text, no labels, no letters, no compass text, no watermark, no UI. Use the reference image only for palette and mood. Four regions laid out from left to right: on the far left a deep green pine forest with tiny fireflies; then amber sand dunes with small glowing crystal spires; then a snowy blue-white mountain pass; on the far right a ruined golden city with a giant brazier on its central gate. A dotted road winds through all four regions from left to right. Edges and corners of the parchment are darkened and burnt, warm vignette."),
 "panel":("gpt_image_2_6","1:1",[],f"Game UI asset, flat front view, no perspective: a square 9-slice panel frame for a fantasy RPG menu, made of dark polished wood with ornate engraved brass corner pieces and thin brass edge trim, slightly pixel-art styled, warm ember lighting. The centre of the panel is a large empty plain dark-wood area with subtle grain, no ornaments in the centre. The frame fills almost the whole image with a small margin. No text, no icons, no watermark. Outside the frame: {MAG}"),
}
reqs=[]
for i,(k,(m,a,refs,p)) in enumerate(P.items()):
  par={"model":m,"aspect_ratio":a,"resolution":"2k","use_unlim":False,"prompt":p}
  if m=="gpt_image_2_6": par["quality"]="high"
  if refs: par["medias"]=[{"value":r,"role":"image_references"} for r in refs]
  reqs.append({"index":i,"key":k,"params":par})
json.dump(reqs,open("reqs_t11.json","w"),indent=1)
